"""
内容转换模块（增强版）
职责：将EPUB HTML内容转换为Notion Blocks格式
特性：
- 支持更多HTML元素（code, pre, hr, table等）
- 保留富文本格式（粗体、斜体、链接等）
- 智能分割长文本
- 图片处理支持
"""
import sys
import traceback
import re
from typing import List, Dict, Any, Optional, Tuple
from dataclasses import dataclass, field

from bs4 import BeautifulSoup, NavigableString, Tag
from loguru import logger

from image_handler import ImageHandler, NotionImageBlockBuilder


@dataclass
class RichTextSegment:
    """富文本片段"""
    text: str
    bold: bool = False
    italic: bool = False
    strikethrough: bool = False
    underline: bool = False
    code: bool = False
    color: str = "default"
    link: Optional[str] = None

    def to_notion_format(self) -> Dict[str, Any]:
        """转换为Notion rich_text格式"""
        result = {
            "type": "text",
            "text": {"content": self.text}
        }

        # 添加链接
        if self.link:
            result["text"]["link"] = {"url": self.link}

        # 添加样式注解
        annotations = {}
        if self.bold:
            annotations["bold"] = True
        if self.italic:
            annotations["italic"] = True
        if self.strikethrough:
            annotations["strikethrough"] = True
        if self.underline:
            annotations["underline"] = True
        if self.code:
            annotations["code"] = True
        if self.color != "default":
            annotations["color"] = self.color

        if annotations:
            result["annotations"] = annotations

        return result


@dataclass
class NotionBlock:
    """Notion Block数据类"""
    type: str
    content: Dict[str, Any]
    children: List["NotionBlock"] = field(default_factory=list)

    def to_dict(self) -> Dict[str, Any]:
        """转换为Notion API所需的字典格式"""
        result = {
            "object": "block",
            "type": self.type,
            self.type: self.content
        }

        # 添加子块（如果有）
        if self.children:
            result[self.type]["children"] = [
                child.to_dict() for child in self.children
            ]

        return result


class ContentConverter:
    """
    内容转换器（增强版）
    职责：HTML -> Notion Blocks
    特性：
    - 保留富文本格式
    - 支持更多HTML元素
    - 智能长文本分割
    - 图片处理
    """

    # Notion rich_text 最大长度
    MAX_RICH_TEXT_LENGTH = 2000

    # HTML标签到Notion样式的映射
    STYLE_TAGS = {
        'strong': {'bold': True},
        'b': {'bold': True},
        'em': {'italic': True},
        'i': {'italic': True},
        'u': {'underline': True},
        's': {'strikethrough': True},
        'del': {'strikethrough': True},
        'strike': {'strikethrough': True},
        'code': {'code': True},
        'mark': {'color': 'yellow_background'},
    }

    def __init__(
        self,
        max_text_length: int = 2000,
        split_at_sentence: bool = True,
        image_handler: Optional[ImageHandler] = None,
        preserve_formatting: bool = True
    ):
        """
        初始化转换器

        Args:
            max_text_length: 单个文本块最大长度
            split_at_sentence: 是否在句子边界分割
            image_handler: 图片处理器实例
            preserve_formatting: 是否保留富文本格式
        """
        self.max_text_length = min(max_text_length, self.MAX_RICH_TEXT_LENGTH)
        self.split_at_sentence = split_at_sentence
        self.image_handler = image_handler
        self.preserve_formatting = preserve_formatting

        # 用于存储当前处理的图片
        self._current_images: Dict[str, Any] = {}

    def convert_html_to_blocks(
        self,
        html_content: str,
        images: Optional[Dict[str, Any]] = None
    ) -> List[Dict[str, Any]]:
        """
        将HTML内容转换为Notion blocks

        Args:
            html_content: HTML字符串
            images: 图片数据字典（href -> ImageData）

        Returns:
            Notion blocks列表
        """
        try:
            self._current_images = images or {}

            soup = BeautifulSoup(html_content, 'html.parser')

            # 移除script和style
            for tag in soup(['script', 'style', 'head']):
                tag.decompose()

            # 处理body内容
            body = soup.find('body')
            if not body:
                body = soup

            blocks = []
            for element in body.children:
                if isinstance(element, NavigableString):
                    text = str(element).strip()
                    if text:
                        blocks.extend(self._create_paragraph_blocks_rich(text))
                elif isinstance(element, Tag):
                    converted = self._convert_element(element)
                    if converted:
                        if isinstance(converted, list):
                            blocks.extend(converted)
                        else:
                            blocks.append(converted)

            logger.debug(f"转换HTML: {len(blocks)} blocks")
            return [b.to_dict() if isinstance(b, NotionBlock) else b for b in blocks]

        except Exception as e:
            exc_type, exc_value, exc_traceback = sys.exc_info()
            error_message = repr(traceback.format_exception(exc_type, exc_value, exc_traceback))
            logger.error(f"HTML转换失败: {error_message}")
            return []

    def _convert_element(self, element: Tag) -> Optional[Any]:
        """转换单个HTML元素"""
        tag_name = element.name.lower() if element.name else ''

        # 标题 h1-h6
        if tag_name in ['h1', 'h2', 'h3', 'h4', 'h5', 'h6']:
            return self._create_heading_block(element, tag_name)

        # 段落
        elif tag_name == 'p':
            return self._convert_paragraph(element)

        # 引用
        elif tag_name == 'blockquote':
            return self._create_quote_block(element)

        # 代码块
        elif tag_name == 'pre':
            return self._create_code_block(element)

        # 行内代码包裹的段落
        elif tag_name == 'code' and element.parent and element.parent.name != 'pre':
            # 行内代码，作为段落处理
            return self._convert_paragraph(element.parent if element.parent.name == 'p' else element)

        # 列表
        elif tag_name in ['ul', 'ol']:
            return self._create_list_blocks(element, tag_name)

        # 分隔线
        elif tag_name == 'hr':
            return self._create_divider_block()

        # 表格
        elif tag_name == 'table':
            return self._create_table_block(element)

        # 图片
        elif tag_name == 'img':
            return self._create_image_block(element)

        # figure（通常包含图片和说明）
        elif tag_name == 'figure':
            return self._convert_figure(element)

        # div/section/article - 递归处理
        elif tag_name in ['div', 'section', 'article', 'span', 'aside']:
            return self._convert_container(element)

        # br - 添加换行
        elif tag_name == 'br':
            return None  # 在富文本中处理

        # 其他未知标签 - 尝试提取文本
        else:
            text = element.get_text(strip=True)
            if text:
                return self._create_paragraph_blocks_rich(text)
            return None

    def _convert_paragraph(self, element: Tag) -> Optional[List[NotionBlock]]:
        """转换段落元素"""
        # 检查是否只包含图片
        if element.find('img') and not element.get_text(strip=True):
            img = element.find('img')
            return self._create_image_block(img)

        # 提取富文本
        rich_text = self._extract_rich_text(element)
        if not rich_text:
            return None

        return self._create_paragraph_blocks_from_rich_text(rich_text)

    def _extract_rich_text(self, element: Tag) -> List[RichTextSegment]:
        """
        从HTML元素提取富文本片段

        Args:
            element: HTML元素

        Returns:
            RichTextSegment列表
        """
        segments = []

        def process_node(node, inherited_styles: Dict[str, Any] = None):
            """递归处理节点"""
            if inherited_styles is None:
                inherited_styles = {}

            if isinstance(node, NavigableString):
                text = str(node)
                if text.strip() or text:  # 保留有意义的空格
                    # 清理多余空白但保留单个空格
                    text = re.sub(r'\s+', ' ', text)
                    if text:
                        segments.append(RichTextSegment(
                            text=text,
                            **inherited_styles
                        ))

            elif isinstance(node, Tag):
                tag_name = node.name.lower() if node.name else ''

                # 跳过某些标签
                if tag_name in ['script', 'style', 'head']:
                    return

                # 处理链接
                if tag_name == 'a':
                    href = node.get('href', '')
                    new_styles = {**inherited_styles, 'link': href if href else None}
                    for child in node.children:
                        process_node(child, new_styles)
                    return

                # 处理样式标签
                if tag_name in self.STYLE_TAGS:
                    new_styles = {**inherited_styles, **self.STYLE_TAGS[tag_name]}
                    for child in node.children:
                        process_node(child, new_styles)
                    return

                # 处理换行
                if tag_name == 'br':
                    segments.append(RichTextSegment(text='\n', **inherited_styles))
                    return

                # 其他标签 - 递归处理子元素
                for child in node.children:
                    process_node(child, inherited_styles)

        process_node(element)

        # 合并相邻的相同样式片段
        if self.preserve_formatting:
            segments = self._merge_segments(segments)

        return segments

    def _merge_segments(self, segments: List[RichTextSegment]) -> List[RichTextSegment]:
        """合并相邻的相同样式片段"""
        if not segments:
            return []

        merged = []
        current = segments[0]

        for segment in segments[1:]:
            # 检查样式是否相同
            same_style = (
                current.bold == segment.bold and
                current.italic == segment.italic and
                current.strikethrough == segment.strikethrough and
                current.underline == segment.underline and
                current.code == segment.code and
                current.color == segment.color and
                current.link == segment.link
            )

            if same_style:
                # 合并文本
                current = RichTextSegment(
                    text=current.text + segment.text,
                    bold=current.bold,
                    italic=current.italic,
                    strikethrough=current.strikethrough,
                    underline=current.underline,
                    code=current.code,
                    color=current.color,
                    link=current.link
                )
            else:
                if current.text:
                    merged.append(current)
                current = segment

        if current.text:
            merged.append(current)

        return merged

    def _create_paragraph_blocks_from_rich_text(
        self,
        rich_text: List[RichTextSegment]
    ) -> List[NotionBlock]:
        """从富文本片段创建段落blocks"""
        blocks = []

        # 计算总长度
        total_length = sum(len(seg.text) for seg in rich_text)

        if total_length <= self.max_text_length:
            # 不需要分割
            blocks.append(NotionBlock(
                type="paragraph",
                content={
                    "rich_text": [seg.to_notion_format() for seg in rich_text if seg.text.strip()]
                }
            ))
        else:
            # 需要分割
            current_segments = []
            current_length = 0

            for segment in rich_text:
                if current_length + len(segment.text) <= self.max_text_length:
                    current_segments.append(segment)
                    current_length += len(segment.text)
                else:
                    # 保存当前块
                    if current_segments:
                        blocks.append(NotionBlock(
                            type="paragraph",
                            content={
                                "rich_text": [seg.to_notion_format() for seg in current_segments if seg.text.strip()]
                            }
                        ))

                    # 处理当前片段（可能需要进一步分割）
                    if len(segment.text) > self.max_text_length:
                        # 分割长片段
                        text_chunks = self._split_text(segment.text)
                        for chunk in text_chunks:
                            blocks.append(NotionBlock(
                                type="paragraph",
                                content={
                                    "rich_text": [RichTextSegment(
                                        text=chunk,
                                        bold=segment.bold,
                                        italic=segment.italic,
                                        strikethrough=segment.strikethrough,
                                        underline=segment.underline,
                                        code=segment.code,
                                        color=segment.color,
                                        link=segment.link
                                    ).to_notion_format()]
                                }
                            ))
                        current_segments = []
                        current_length = 0
                    else:
                        current_segments = [segment]
                        current_length = len(segment.text)

            # 保存剩余内容
            if current_segments:
                blocks.append(NotionBlock(
                    type="paragraph",
                    content={
                        "rich_text": [seg.to_notion_format() for seg in current_segments if seg.text.strip()]
                    }
                ))

        return blocks

    def _create_paragraph_blocks_rich(self, text: str) -> List[NotionBlock]:
        """从纯文本创建段落blocks"""
        segments = [RichTextSegment(text=text)]
        return self._create_paragraph_blocks_from_rich_text(segments)

    def _create_heading_block(self, element: Tag, tag_name: str) -> NotionBlock:
        """创建标题block"""
        level = int(tag_name[1])  # 'h1' -> 1

        # Notion只支持heading_1, heading_2, heading_3
        if level > 3:
            level = 3

        # 提取富文本
        rich_text = self._extract_rich_text(element)

        return NotionBlock(
            type=f"heading_{level}",
            content={
                "rich_text": [seg.to_notion_format() for seg in rich_text] if rich_text else [
                    {"type": "text", "text": {"content": element.get_text(strip=True)}}
                ]
            }
        )

    def _create_quote_block(self, element: Tag) -> NotionBlock:
        """创建引用block"""
        rich_text = self._extract_rich_text(element)

        # 限制长度
        total_length = sum(len(seg.text) for seg in rich_text)
        if total_length > self.max_text_length:
            # 截断
            text = element.get_text(strip=True)
            text = text[:self.max_text_length - 3] + "..."
            rich_text = [RichTextSegment(text=text)]

        return NotionBlock(
            type="quote",
            content={
                "rich_text": [seg.to_notion_format() for seg in rich_text]
            }
        )

    def _create_code_block(self, element: Tag) -> NotionBlock:
        """创建代码块"""
        # 尝试检测语言
        language = "plain text"
        code_tag = element.find('code')

        if code_tag:
            # 从class属性检测语言
            classes = code_tag.get('class', [])
            for cls in classes:
                if cls.startswith('language-'):
                    language = cls[9:]
                    break
                elif cls.startswith('lang-'):
                    language = cls[5:]
                    break

            code_text = code_tag.get_text()
        else:
            code_text = element.get_text()

        # 限制代码长度
        if len(code_text) > self.max_text_length:
            code_text = code_text[:self.max_text_length - 20] + "\n... [代码已截断]"

        return NotionBlock(
            type="code",
            content={
                "rich_text": [{"type": "text", "text": {"content": code_text}}],
                "language": language
            }
        )

    def _create_list_blocks(self, element: Tag, list_type: str) -> List[NotionBlock]:
        """创建列表blocks"""
        block_type = "bulleted_list_item" if list_type == "ul" else "numbered_list_item"
        blocks = []

        for li in element.find_all('li', recursive=False):
            # 提取富文本
            rich_text = self._extract_rich_text(li)

            if rich_text:
                # 检查是否有嵌套列表
                nested_list = li.find(['ul', 'ol'], recursive=False)

                block = NotionBlock(
                    type=block_type,
                    content={
                        "rich_text": [seg.to_notion_format() for seg in rich_text]
                    }
                )

                # 处理嵌套列表（Notion支持列表项的children）
                if nested_list:
                    nested_blocks = self._create_list_blocks(
                        nested_list,
                        nested_list.name
                    )
                    block.children = nested_blocks

                blocks.append(block)

        return blocks

    def _create_divider_block(self) -> NotionBlock:
        """创建分隔线block"""
        return NotionBlock(
            type="divider",
            content={}
        )

    def _create_table_block(self, element: Tag) -> List[NotionBlock]:
        """创建表格block"""
        rows = []

        # 提取所有行
        for tr in element.find_all('tr'):
            row = []
            for cell in tr.find_all(['th', 'td']):
                cell_text = cell.get_text(strip=True)
                # 截断过长的单元格
                if len(cell_text) > 200:
                    cell_text = cell_text[:197] + "..."
                row.append(cell_text)
            if row:
                rows.append(row)

        if not rows:
            return []

        # 确定列数
        max_cols = max(len(row) for row in rows)

        # 创建表格block
        table_rows = []
        for row in rows:
            # 补齐列数
            while len(row) < max_cols:
                row.append("")

            table_rows.append({
                "type": "table_row",
                "table_row": {
                    "cells": [
                        [{"type": "text", "text": {"content": cell}}]
                        for cell in row
                    ]
                }
            })

        # 注意：Notion表格需要先创建，然后添加行作为children
        # 这里返回一个特殊结构
        return [NotionBlock(
            type="table",
            content={
                "table_width": max_cols,
                "has_column_header": True,
                "has_row_header": False,
                "children": table_rows
            }
        )]

    def _create_image_block(self, element: Tag) -> Optional[Any]:
        """创建图片block"""
        src = element.get('src', '')
        alt = element.get('alt', '')

        if not src:
            return None

        # 如果有图片处理器，尝试处理图片
        if self.image_handler and src in self._current_images:
            image_data = self._current_images[src]
            processed = self.image_handler.process_image(
                image_data.content,
                src,
                image_data.media_type
            )

            if processed and processed.url.startswith('http'):
                return NotionImageBlockBuilder.create_image_block(
                    processed.url,
                    alt
                )

        # 如果是外部URL，直接使用
        if src.startswith('http'):
            return NotionImageBlockBuilder.create_image_block(src, alt)

        # 否则创建占位符
        return NotionImageBlockBuilder.create_placeholder_block(
            src,
            f"图片说明: {alt}" if alt else "图片无法显示"
        )

    def _convert_figure(self, element: Tag) -> Optional[Any]:
        """转换figure元素（图片+说明）"""
        blocks = []

        # 处理图片
        img = element.find('img')
        if img:
            img_block = self._create_image_block(img)
            if img_block:
                blocks.append(img_block)

        # 处理说明
        figcaption = element.find('figcaption')
        if figcaption:
            caption_text = figcaption.get_text(strip=True)
            if caption_text:
                # 使用斜体的段落作为图片说明
                blocks.append(NotionBlock(
                    type="paragraph",
                    content={
                        "rich_text": [
                            RichTextSegment(text=caption_text, italic=True).to_notion_format()
                        ]
                    }
                ))

        return blocks if blocks else None

    def _convert_container(self, element: Tag) -> Optional[List]:
        """转换容器元素（div, section等）"""
        blocks = []

        for child in element.children:
            if isinstance(child, Tag):
                converted = self._convert_element(child)
                if converted:
                    if isinstance(converted, list):
                        blocks.extend(converted)
                    else:
                        blocks.append(converted)
            elif isinstance(child, NavigableString):
                text = str(child).strip()
                if text:
                    blocks.extend(self._create_paragraph_blocks_rich(text))

        return blocks if blocks else None

    def _split_text(self, text: str) -> List[str]:
        """分割长文本"""
        if len(text) <= self.max_text_length:
            return [text]

        chunks = []
        remaining = text

        while remaining:
            if len(remaining) <= self.max_text_length:
                chunks.append(remaining)
                break

            chunk = remaining[:self.max_text_length]

            # 尝试在句子边界分割
            if self.split_at_sentence:
                last_period = max(
                    chunk.rfind('。'),
                    chunk.rfind('！'),
                    chunk.rfind('？'),
                    chunk.rfind('.'),
                    chunk.rfind('!'),
                    chunk.rfind('?'),
                    chunk.rfind('\n')
                )

                if last_period > self.max_text_length * 0.5:
                    chunk = chunk[:last_period + 1]

            chunks.append(chunk)
            remaining = remaining[len(chunk):]

        return chunks

    def convert_text_to_blocks(self, text: str, block_type: str = "paragraph") -> List[Dict[str, Any]]:
        """将纯文本转换为blocks"""
        if not text or not text.strip():
            return []

        paragraphs = [p.strip() for p in text.split('\n') if p.strip()]

        blocks = []
        for para in paragraphs:
            chunks = self._split_text(para)
            for chunk in chunks:
                blocks.append({
                    "object": "block",
                    "type": block_type,
                    block_type: {
                        "rich_text": [{"type": "text", "text": {"content": chunk}}]
                    }
                })

        return blocks


# 测试函数
def test_content_converter():
    """测试内容转换器"""
    from loguru import logger
    import sys
    logger.add(sys.stderr, level="DEBUG")

    # 测试HTML
    html_content = """
    <html>
    <body>
        <h1>第一章 童年</h1>
        <p>朱元璋，<strong>濠州钟离人</strong>，祖籍<em>江苏句容</em>。</p>
        <p>这是一段包含<a href="https://example.com">链接</a>的文本。</p>
        <p>这是一个很长的段落，包含了很多内容。""" + "测试文本" * 200 + """</p>
        <h2>早年经历</h2>
        <blockquote>天生异象，<strong>注定不凡</strong></blockquote>
        <pre><code class="language-python">def hello():
    print("Hello, World!")</code></pre>
        <ul>
            <li>第一点：<em>重要内容</em></li>
            <li>第二点
                <ul>
                    <li>嵌套第一点</li>
                    <li>嵌套第二点</li>
                </ul>
            </li>
        </ul>
        <hr/>
        <table>
            <tr><th>姓名</th><th>年龄</th></tr>
            <tr><td>张三</td><td>25</td></tr>
        </table>
    </body>
    </html>
    """

    converter = ContentConverter(max_text_length=500)
    blocks = converter.convert_html_to_blocks(html_content)

    logger.info(f"生成了 {len(blocks)} 个blocks")
    for i, block in enumerate(blocks[:10]):
        logger.info(f"Block {i+1}: {block['type']}")
        if block['type'] == 'paragraph':
            rich_text = block['paragraph'].get('rich_text', [])
            if rich_text:
                preview = rich_text[0].get('text', {}).get('content', '')[:50]
                logger.info(f"  内容预览: {preview}...")


if __name__ == "__main__":
    test_content_converter()

"""
Notion 块转换模块
职责：将论文内容转换为丰富的 Notion blocks
遵循 CleanRL 设计原则：单一职责、显式依赖、易于测试

支持的 Notion 元素：
- heading_1/2/3: 标题
- paragraph: 段落（支持富文本）
- callout: 提示框（摘要、警告等）
- quote: 引用
- code: 代码块
- equation: 数学公式
- table: 表格
- bulleted_list_item: 无序列表
- numbered_list_item: 有序列表
- divider: 分隔线
- toggle: 可折叠内容
- image: 图片
- bookmark: 链接预览
