"""
Notion 内容转换服务
将论文/书籍内容转换为 Notion blocks
"""
import re
from typing import List, Dict, Any, Optional
from datetime import datetime

from loguru import logger


class NotionConverter:
    """
    Notion 内容转换器

    支持的 Notion 元素：
    - heading_1/2/3: 标题
    - paragraph: 段落（富文本）
    - callout: 提示框
    - quote: 引用
    - code: 代码块
    - equation: 公式
    - table: 表格
    - bulleted_list_item: 无序列表
    - numbered_list_item: 有序列表
    - divider: 分隔线
    - toggle: 折叠
    - image: 图片
    - bookmark: 书签
    - table_of_contents: 目录
    """

    MAX_TEXT_LENGTH = 2000

    def __init__(
        self,
        max_text_length: int = 2000,
        include_equations: bool = True,
        include_tables: bool = True,
        include_images: bool = True,
    ):
        """
        初始化转换器
        """
        self.max_text_length = max_text_length
        self.include_equations = include_equations
        self.include_tables = include_tables
        self.include_images = include_images

    # ========== Block Builders ==========

    def _rich_text(
        self,
        text: str,
        bold: bool = False,
        italic: bool = False,
        code: bool = False,
        color: str = "default",
        link: Optional[str] = None,
    ) -> Dict:
        """创建富文本对象"""
        if len(text) > self.max_text_length:
            text = text[:self.max_text_length - 3] + "..."

        result = {
            "type": "text",
            "text": {"content": text}
        }

        if link:
            result["text"]["link"] = {"url": link}

        annotations = {}
        if bold:
            annotations["bold"] = True
        if italic:
            annotations["italic"] = True
        if code:
            annotations["code"] = True
        if color != "default":
            annotations["color"] = color

        if annotations:
            result["annotations"] = annotations

        return result

    def _heading(self, text: str, level: int = 1) -> Dict:
        """创建标题"""
        level = max(1, min(3, level))
        block_type = f"heading_{level}"

        return {
            "object": "block",
            "type": block_type,
            block_type: {
                "rich_text": [self._rich_text(text)]
            }
        }

    def _paragraph(self, text: str, **kwargs) -> Dict:
        """创建段落"""
        return {
            "object": "block",
            "type": "paragraph",
            "paragraph": {
                "rich_text": [self._rich_text(text, **kwargs)]
            }
        }

    def _paragraph_rich(self, rich_texts: List[Dict]) -> Dict:
        """创建带多个富文本的段落"""
        return {
            "object": "block",
            "type": "paragraph",
            "paragraph": {
                "rich_text": rich_texts
            }
        }

    def _callout(self, text: str, icon: str = "💡", color: str = "gray_background") -> Dict:
        """创建提示框"""
        return {
            "object": "block",
            "type": "callout",
            "callout": {
                "rich_text": [self._rich_text(text)],
                "icon": {"emoji": icon},
                "color": color,
            }
        }

    def _quote(self, text: str) -> Dict:
        """创建引用"""
        return {
            "object": "block",
            "type": "quote",
            "quote": {
                "rich_text": [self._rich_text(text)]
            }
        }

    def _equation(self, latex: str) -> Dict:
        """创建公式"""
        return {
            "object": "block",
            "type": "equation",
            "equation": {
                "expression": latex
            }
        }

    def _divider(self) -> Dict:
        """创建分隔线"""
        return {
            "object": "block",
            "type": "divider",
            "divider": {}
        }

    def _bulleted_list_item(self, text: str) -> Dict:
        """创建无序列表项"""
        return {
            "object": "block",
            "type": "bulleted_list_item",
            "bulleted_list_item": {
                "rich_text": [self._rich_text(text)]
            }
        }

    def _numbered_list_item(self, text: str) -> Dict:
        """创建有序列表项"""
        return {
            "object": "block",
            "type": "numbered_list_item",
            "numbered_list_item": {
                "rich_text": [self._rich_text(text)]
            }
        }

    def _image(self, url: str, caption: Optional[str] = None) -> Dict:
        """创建图片"""
        block = {
            "object": "block",
            "type": "image",
            "image": {
                "type": "external",
                "external": {"url": url}
            }
        }
        if caption:
            block["image"]["caption"] = [self._rich_text(caption)]
        return block

    def _bookmark(self, url: str, caption: Optional[str] = None) -> Dict:
        """创建书签"""
        block = {
            "object": "block",
            "type": "bookmark",
            "bookmark": {"url": url}
        }
        if caption:
            block["bookmark"]["caption"] = [self._rich_text(caption)]
        return block

    def _table(self, headers: List[str], rows: List[List[str]]) -> Dict:
        """创建表格"""
        table_width = len(headers) if headers else (len(rows[0]) if rows else 1)

        table_rows = []

        # 表头
        if headers:
            table_rows.append({
                "type": "table_row",
                "table_row": {
                    "cells": [[self._rich_text(h)] for h in headers]
                }
            })

        # 数据行
        for row in rows[:30]:  # 限制行数
            padded_row = row + [""] * (table_width - len(row))
            table_rows.append({
                "type": "table_row",
                "table_row": {
                    "cells": [[self._rich_text(cell)] for cell in padded_row[:table_width]]
                }
            })

        return {
            "object": "block",
            "type": "table",
            "table": {
                "table_width": table_width,
                "has_column_header": bool(headers),
                "has_row_header": False,
                "children": table_rows
            }
        }

    def _table_of_contents(self) -> Dict:
        """创建目录"""
        return {
            "object": "block",
            "type": "table_of_contents",
            "table_of_contents": {"color": "default"}
        }

    # ========== Paper Conversion ==========

    def convert_paper(self, paper_data: Dict[str, Any]) -> List[Dict]:
        """
        转换论文数据为 Notion blocks

        Args:
            paper_data: 包含 metadata, content, resolved_references

        Returns:
            Notion blocks 列表
        """
        blocks = []

        metadata = paper_data.get("metadata", {})
        content = paper_data.get("content", {})
        references = paper_data.get("resolved_references", [])
        arxiv_id = paper_data.get("arxiv_id", "")

        # 1. 元数据头部
        blocks.extend(self._create_paper_header(metadata, arxiv_id))

        # 2. 摘要
        abstract = content.get("abstract") or metadata.get("abstract")
        if abstract:
            blocks.append(self._heading("📝 Abstract", 2))
            blocks.append(self._quote(abstract))

        # 3. 目录
        blocks.append(self._divider())
        blocks.append(self._heading("📑 Table of Contents", 2))
        blocks.append(self._table_of_contents())
        blocks.append(self._divider())

        # 4. 章节内容
        if content and content.get("sections"):
            for section in content.get("sections", [])[:50]:
                blocks.extend(self._convert_section(section))

        # 5. 参考文献
        if references:
            blocks.extend(self._create_references_section(references))

        return blocks

    def _create_paper_header(self, metadata: Dict, arxiv_id: str) -> List[Dict]:
        """创建论文头部信息"""
        blocks = []

        if metadata:
            # 信息 callout
            authors = metadata.get("authors", [])
            author_names = ", ".join([a.get("name", "") for a in authors[:3]])
            if len(authors) > 3:
                author_names += f" et al. ({len(authors)} authors)"

            published = metadata.get("published", "")
            if isinstance(published, datetime):
                published = published.strftime("%Y-%m-%d")

            categories = metadata.get("categories", [])

            info_text = f"📅 Published: {published}\n"
            info_text += f"👥 Authors: {author_names}\n"
            info_text += f"🏷️ Categories: {', '.join(categories[:5])}"

            if metadata.get("doi"):
                info_text += f"\n🔗 DOI: {metadata.get('doi')}"

            blocks.append(self._callout(info_text, icon="📄", color="blue_background"))

        # 链接
        if arxiv_id:
            arxiv_url = f"https://arxiv.org/abs/{arxiv_id}"
            pdf_url = f"https://arxiv.org/pdf/{arxiv_id}.pdf"
            ar5iv_url = f"https://ar5iv.labs.arxiv.org/html/{arxiv_id}"

            blocks.append(self._paragraph_rich([
                self._rich_text("🔗 Links: ", bold=True),
                self._rich_text("arXiv", link=arxiv_url, color="blue"),
                self._rich_text(" | "),
                self._rich_text("PDF", link=pdf_url, color="blue"),
                self._rich_text(" | "),
                self._rich_text("ar5iv", link=ar5iv_url, color="blue"),
            ]))

        blocks.append(self._divider())

        return blocks

    def _convert_section(self, section: Dict, depth: int = 0) -> List[Dict]:
        """转换章节"""
        blocks = []

        level = min(section.get("level", 2), 3)
        title = section.get("title", "")

        if title:
            blocks.append(self._heading(title, level))

        # 段落
        for para in section.get("paragraphs", []):
            if len(para) > self.max_text_length:
                # 分割长段落
                for chunk in self._split_text(para):
                    blocks.append(self._paragraph(chunk))
            else:
                blocks.append(self._paragraph(para))

        # 公式
        if self.include_equations:
            for eq in section.get("equations", [])[:10]:
                if eq.get("latex"):
                    blocks.append(self._equation(eq.get("latex")))

        # 图片
        if self.include_images:
            for fig in section.get("figures", [])[:5]:
                if fig.get("src") and fig.get("src").startswith("http"):
                    blocks.append(self._image(fig.get("src"), fig.get("caption")))

        # 表格
        if self.include_tables:
            for table in section.get("tables", [])[:3]:
                if table.get("headers") or table.get("rows"):
                    blocks.append(self._table(
                        table.get("headers", []),
                        table.get("rows", [])
                    ))

        # 子章节
        for subsection in section.get("subsections", []):
            blocks.extend(self._convert_section(subsection, depth + 1))

        return blocks

    def _create_references_section(self, references: List[Dict]) -> List[Dict]:
        """创建参考文献部分"""
        blocks = []

        blocks.append(self._divider())
        blocks.append(self._heading("📚 References", 2))

        # 统计
        arxiv_refs = [r for r in references if r.get("arxiv_id")]
        if arxiv_refs:
            blocks.append(self._callout(
                f"🔗 Found {len(arxiv_refs)} arXiv references (sub-pages created)",
                icon="📄",
                color="green_background"
            ))

        # 参考文献列表
        for ref in references[:100]:
            raw_text = ref.get("raw_text", "")
            if len(raw_text) > 500:
                raw_text = raw_text[:497] + "..."

            if ref.get("arxiv_id"):
                arxiv_url = f"https://arxiv.org/abs/{ref.get('arxiv_id')}"
                blocks.append(self._paragraph_rich([
                    self._rich_text(f"[{ref.get('citation_key', '?')}] ", bold=True),
                    self._rich_text(raw_text[:200] + "... ", italic=True),
                    self._rich_text(f"[arXiv:{ref.get('arxiv_id')}]", link=arxiv_url, color="blue"),
                ]))
            else:
                blocks.append(self._bulleted_list_item(
                    f"[{ref.get('citation_key', '?')}] {raw_text}"
                ))

        return blocks

    def _split_text(self, text: str) -> List[str]:
        """分割长文本"""
        if len(text) <= self.max_text_length:
            return [text]

        chunks = []
        remaining = text

        while remaining:
            if len(remaining) <= self.max_text_length:
                chunks.append(remaining)
                break

            chunk = remaining[:self.max_text_length]

            # 尝试在句子边界分割
            last_period = max(
                chunk.rfind('. '),
                chunk.rfind('。'),
                chunk.rfind('! '),
                chunk.rfind('? '),
            )

            if last_period > self.max_text_length * 0.5:
                chunk = chunk[:last_period + 1]

            chunks.append(chunk.strip())
            remaining = remaining[len(chunk):].strip()

        return chunks

    # ========== Book Conversion ==========

    def convert_book(
        self,
        book_data: Dict[str, Any],
        include_toc: bool = True,
    ) -> List[Dict]:
        """
        转换书籍数据为 Notion blocks

        Args:
            book_data: 包含 title, authors, chapters, toc
            include_toc: 是否包含目录

        Returns:
            Notion blocks 列表
        """
        blocks = []

        title = book_data.get("title", "Untitled Book")
        authors = book_data.get("authors", [])

        # 1. 书籍信息
        info_text = f"📚 {title}\n"
        if authors:
            info_text += f"✍️ By: {', '.join(authors)}"

        blocks.append(self._callout(info_text, icon="📚", color="blue_background"))

        # 2. 目录
        if include_toc:
            blocks.append(self._divider())
            blocks.append(self._heading("📖 Table of Contents", 2))
            blocks.append(self._table_of_contents())
            blocks.append(self._divider())

        # 3. 章节内容（简化版，详细内容在子页面）
        toc = book_data.get("toc", [])
        if toc:
            blocks.append(self._heading("📑 Chapters", 2))
            for item in toc[:50]:
                blocks.append(self._bulleted_list_item(item.get("title", "")))

        return blocks

import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { useState, useEffect } from 'react';
import Header from './components/Header';
import Footer from './components/Footer';
import Home from './pages/Home';
import Bookwise from './pages/Bookwise';
import Paperwise from './pages/Paperwise';
import Callback from './pages/Callback';

// API base URL
const API_BASE = import.meta.env.VITE_API_URL || 'http://localhost:8000';

interface AuthState {
  authenticated: boolean;
  workspaceName?: string;
  workspaceId?: string;
  loading: boolean;
}

function App() {
  const [auth, setAuth] = useState<AuthState>({
    authenticated: false,
    loading: true,
  });

  // Check auth status on mount
  useEffect(() => {
    checkAuthStatus();
  }, []);

  const checkAuthStatus = async () => {
    try {
      const sessionId = localStorage.getItem('wise_session');
      if (!sessionId) {
        setAuth({ authenticated: false, loading: false });
        return;
      }

      const response = await fetch(
        `${API_BASE}/auth/status?session_id=${sessionId}`,
        { credentials: 'include' }
      );
      const data = await response.json();

      if (data.success && data.data?.authenticated) {
        setAuth({
          authenticated: true,
          workspaceName: data.data.workspace_name,
          workspaceId: data.data.workspace_id,
          loading: false,
        });
      } else {
        localStorage.removeItem('wise_session');
        setAuth({ authenticated: false, loading: false });
      }
    } catch (error) {
      console.error('Auth check failed:', error);
      setAuth({ authenticated: false, loading: false });
    }
  };

  const handleLogin = () => {
    window.location.href = `${API_BASE}/auth/login`;
  };

  const handleLogout = async () => {
    const sessionId = localStorage.getItem('wise_session');
    try {
      await fetch(`${API_BASE}/auth/logout?session_id=${sessionId}`, {
        method: 'POST',
        credentials: 'include',
      });
    } catch (error) {
      console.error('Logout failed:', error);
    }
    localStorage.removeItem('wise_session');
    setAuth({ authenticated: false, loading: false });
  };

  const handleAuthSuccess = (sessionId: string) => {
    localStorage.setItem('wise_session', sessionId);
    checkAuthStatus();
  };

  if (auth.loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="animate-spin rounded-full h-12 w-12 border-4 border-blue-500 border-t-transparent" />
      </div>
    );
  }

  return (
    <BrowserRouter>
      <div className="min-h-screen flex flex-col bg-gray-50">
        <Header
          authenticated={auth.authenticated}
          workspaceName={auth.workspaceName}
          onLogin={handleLogin}
          onLogout={handleLogout}
        />

        <main className="flex-1">
          <Routes>
            <Route
              path="/"
              element={
                <Home
                  authenticated={auth.authenticated}
                  onLogin={handleLogin}
                />
              }
            />
            <Route
              path="/bookwise"
              element={
                auth.authenticated ? (
                  <Bookwise />
                ) : (
                  <Navigate to="/" replace />
                )
              }
            />
            <Route
              path="/paperwise"
              element={
                auth.authenticated ? (
                  <Paperwise />
                ) : (
                  <Navigate to="/" replace />
                )
              }
            />
            <Route
              path="/auth/success"
              element={<Callback onSuccess={handleAuthSuccess} />}
            />
            <Route
              path="/auth/error"
              element={
                <div className="flex items-center justify-center min-h-[60vh]">
                  <div className="text-center">
                    <h1 className="text-2xl font-semibold text-gray-900 mb-2">
                      Authentication Failed
                    </h1>
                    <p className="text-gray-600 mb-4">
                      Something went wrong during login. Please try again.
                    </p>
                    <button
                      onClick={handleLogin}
                      className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                    >
                      Try Again
                    </button>
                  </div>
                </div>
              }
            />
          </Routes>
        </main>

        <Footer />
      </div>
    </BrowserRouter>
  );
}

export default App;

