/**
 * Wise Suite API Client
 * 前端与后端通信的统一接口
 */

const API_BASE = import.meta.env.VITE_API_URL || 'http://localhost:8000';

// ========== Types ==========

export interface ApiResponse<T = unknown> {
  success: boolean;
  message: string;
  data?: T;
}

export interface ErrorResponse {
  success: false;
  error: string;
  detail?: string;
  code?: string;
}

export interface NotionPage {
  id: string;
  title: string;
  icon?: string;
  url?: string;
}

export interface ArxivMetadata {
  arxiv_id: string;
  title: string;
  authors: string[];
  abstract: string;
  categories: string[];
  published: string;
  pdf_url: string;
  ar5iv_url: string;
}

export interface ImportProgress {
  job_id: string;
  status: 'pending' | 'processing' | 'completed' | 'failed';
  progress: number;
  current_step: string;
  error?: string;
  result?: ImportResult;
}

export interface ImportResult {
  success: boolean;
  page_id?: string;
  page_url?: string;
  title: string;
  blocks_created: number;
  children_pages: number;
  duration_seconds: number;
  error?: string;
}

// ========== Helpers ==========

function getSessionId(): string | null {
  return localStorage.getItem('wise_session');
}

async function request<T>(
  endpoint: string,
  options: RequestInit = {}
): Promise<T> {
  const sessionId = getSessionId();
  const url = new URL(endpoint, API_BASE);

  if (sessionId) {
    url.searchParams.set('session_id', sessionId);
  }

  const response = await fetch(url.toString(), {
    ...options,
    credentials: 'include',
    headers: {
      'Content-Type': 'application/json',
      ...options.headers,
    },
  });

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Request failed' }));
    throw new Error(error.error || error.detail || 'Request failed');
  }

  return response.json();
}

// ========== Auth API ==========

export const authApi = {
  /**
   * 获取登录 URL
   */
  getLoginUrl(): string {
    return `${API_BASE}/auth/login`;
  },

  /**
   * 检查认证状态
   */
  async checkStatus(): Promise<{
    authenticated: boolean;
    workspaceId?: string;
    workspaceName?: string;
    userId?: string;
  }> {
    const response = await request<ApiResponse>('/auth/status');
    return response.data || { authenticated: false };
  },

  /**
   * 登出
   */
  async logout(): Promise<void> {
    await request('/auth/logout', { method: 'POST' });
    localStorage.removeItem('wise_session');
  },

  /**
   * 获取可访问的页面列表
   */
  async getPages(): Promise<NotionPage[]> {
    const response = await request<ApiResponse<{ pages: NotionPage[] }>>('/auth/pages');
    return response.data?.pages || [];
  },
};

// ========== EPUB API ==========

export const epubApi = {
  /**
   * 上传 EPUB 文件
   */
  async upload(file: File): Promise<{
    job_id: string;
    metadata: {
      title: string;
      authors: string[];
    };
    total_chapters: number;
    total_words: number;
  }> {
    const formData = new FormData();
    formData.append('file', file);

    const sessionId = getSessionId();
    const url = new URL('/api/epub/upload', API_BASE);
    if (sessionId) {
      url.searchParams.set('session_id', sessionId);
    }

    const response = await fetch(url.toString(), {
      method: 'POST',
      body: formData,
      credentials: 'include',
    });

    if (!response.ok) {
      const error = await response.json().catch(() => ({ error: 'Upload failed' }));
      throw new Error(error.error || error.detail || 'Upload failed');
    }

    const result = await response.json();
    return result.data;
  },

  /**
   * 导入 EPUB 到 Notion
   */
  async import(params: {
    job_id: string;
    target_page_id: string;
    create_nested_pages?: boolean;
    include_toc?: boolean;
    include_images?: boolean;
  }): Promise<{ job_id: string; status: string }> {
    const formData = new FormData();
    formData.append('job_id', params.job_id);
    formData.append('target_page_id', params.target_page_id);
    formData.append('create_nested_pages', String(params.create_nested_pages ?? true));
    formData.append('include_toc', String(params.include_toc ?? true));
    formData.append('include_images', String(params.include_images ?? false));

    const sessionId = getSessionId();
    const url = new URL('/api/epub/import', API_BASE);
    if (sessionId) {
      url.searchParams.set('session_id', sessionId);
    }

    const response = await fetch(url.toString(), {
      method: 'POST',
      body: formData,
      credentials: 'include',
    });

    if (!response.ok) {
      const error = await response.json().catch(() => ({ error: 'Import failed' }));
      throw new Error(error.error || error.detail || 'Import failed');
    }

    return response.json();
  },

  /**
   * 获取导入进度
   */
  async getProgress(jobId: string): Promise<ImportProgress> {
    const response = await request<ApiResponse<ImportProgress>>(
      `/api/epub/progress/${jobId}`
    );
    return response.data!;
  },
};

// ========== arXiv API ==========

export const arxivApi = {
  /**
   * 验证 arXiv ID 并获取元数据
   */
  async validate(arxivId: string): Promise<ArxivMetadata> {
    const response = await request<ApiResponse<ArxivMetadata>>('/api/arxiv/validate', {
      method: 'POST',
      body: JSON.stringify({ arxiv_id: arxivId }),
    });
    return response.data!;
  },

  /**
   * 导入 arXiv 论文到 Notion
   */
  async import(params: {
    arxiv_id: string;
    target_page_id: string;
    import_full_content?: boolean;
    include_equations?: boolean;
    include_tables?: boolean;
    create_ref_pages?: boolean;
    max_ref_pages?: number;
  }): Promise<{ job_id: string; status: string }> {
    return request('/api/arxiv/import', {
      method: 'POST',
      body: JSON.stringify({
        arxiv_id: params.arxiv_id,
        target_page_id: params.target_page_id,
        import_full_content: params.import_full_content ?? true,
        include_equations: params.include_equations ?? true,
        include_tables: params.include_tables ?? true,
        create_ref_pages: params.create_ref_pages ?? true,
        max_ref_pages: params.max_ref_pages ?? 10,
      }),
    });
  },

  /**
   * 获取导入进度
   */
  async getProgress(jobId: string): Promise<ImportProgress> {
    const response = await request<ApiResponse<ImportProgress>>(
      `/api/arxiv/progress/${jobId}`
    );
    return response.data!;
  },

  /**
   * 获取最近导入记录
   */
  async getRecentImports(limit = 10): Promise<ImportProgress[]> {
    const response = await request<ApiResponse<{ imports: ImportProgress[] }>>(
      `/api/arxiv/recent?limit=${limit}`
    );
    return response.data?.imports || [];
  },
};

// ========== Export ==========

export const api = {
  auth: authApi,
  epub: epubApi,
  arxiv: arxivApi,
};

export default api;
